mapper.select:
SELECT 
  FROM public."JPN_単語詳細情報" d
 WHERE d."単語ID" = #{wordId}
   AND d."詳細ID" = #{detailId}

mapper.update:
UPDATE public."JPN_単語詳細情報"
   SET "状態コード" = 'ACTIVE',
       "バージョン" = "バージョン" + 1,
       "更新者アカウントID" = #{accountId},
       "更新元コード" = 'APP',
       "更新日時" = CURRENT_TIMESTAMP
 WHERE "単語ID" = #{wordId}
   AND "詳細ID" = #{detailId}
   AND "バージョン" = #{version}
